// ignore_for_file: prefer_initializing_formals
import 'package:dio/dio.dart';
import 'package:flutter/foundation.dart';

import 'access_token_provider.dart';

/// AD-5 — the one interceptor that owns every outgoing request's headers.
/// `apikey` is sent on every call. `Authorization` carries the anon key only
/// on the three `security: []` operations (signup, login, refresh) and the
/// user's access token on every other (`bearerAuth`) operation.
class HeaderInterceptor extends Interceptor {
  HeaderInterceptor({
    required String anonKey,
    required AccessTokenProvider accessTokenProvider,
  }) : _anonKey = anonKey,
       _accessTokenProvider = accessTokenProvider;

  /// The three operations with `security: []` in the contract — the only
  /// ones that ever send the anon key as the bearer token.
  static const anonKeyOnlyFunctions = {
    'auth-signup',
    'auth-login',
    'auth-refresh',
  };

  final String _anonKey;
  final AccessTokenProvider _accessTokenProvider;

  @override
  void onRequest(
    RequestOptions options,
    RequestInterceptorHandler handler,
  ) async {
    options.headers['apikey'] = _anonKey;

    String function;
    try {
      function = functionNameOf(options.path);
    } catch (error) {
      // A malformed `options.path` must never crash/hang the pipeline (an
      // uncaught throw here, before `handler.next` is called, would leave
      // the request unresolved forever) — proceed as if the function were
      // unrecognized rather than let it propagate.
      debugPrint(
        'HeaderInterceptor: functionNameOf failed ($error) for path '
        '"${options.path}" — treating as unrecognized.',
      );
      function = '';
    }
    if (anonKeyOnlyFunctions.contains(function)) {
      options.headers['Authorization'] = 'Bearer $_anonKey';
    } else {
      String? userToken;
      try {
        userToken = await _accessTokenProvider.readAccessToken();
      } catch (error) {
        // A thrown platform exception from the native secure-storage
        // channel must never crash the request pipeline — proceed as if no
        // token were found rather than let it propagate uncaught. Logged so
        // a genuine bug in a future AccessTokenProvider implementation
        // isn't silently invisible.
        debugPrint(
          'HeaderInterceptor: readAccessToken failed ($error) — proceeding '
          'without an Authorization header.',
        );
        userToken = null;
      }
      if (userToken != null) {
        options.headers['Authorization'] = 'Bearer $userToken';
      }
    }

    handler.next(options);
  }

  /// The `x-cerne-function` name is always the first path segment of a URL
  /// built by `UrlBuilder` (whether [path] is the full absolute URL
  /// `ApiClient` sends to `dio`, or a bare `/function/...` path) — pure, so
  /// it's independently testable.
  static String functionNameOf(String path) {
    final segments = Uri.parse(path).pathSegments;
    return segments.isNotEmpty ? segments.first : '';
  }
}

import 'package:hive_ce/hive_ce.dart';

import '../../core/di/injection_container.dart';
import '../../core/network/api_client.dart';
import '../auth/domain/repositories/session_repository.dart';
import 'data/datasources/entries_remote_data_source.dart';
import 'data/repositories/entries_repository_impl.dart';
import 'domain/repositories/entries_repository.dart';
import 'domain/services/pending_entry_write_tracker.dart';
import 'domain/usecases/save_chat_message_as_entry_use_case.dart';
import 'presentation/cubit/entries_search_cubit.dart';
import 'presentation/cubit/entry_detail_cubit.dart';
import 'presentation/cubit/meus_registros_cubit.dart';

/// The `entries` Hive box's name — the first `hive_ce` box in the app
/// (Code Map). A raw `Box<Map>`, not a generated `HiveObject`/
/// `TypeAdapter` (Design Notes: avoids adapter codegen) — spec-4-1's
/// `EntriesRepositoryImpl.list()` is this box's first reader
/// (`create()`'s own writes were, until then, never read back by
/// anything).
const entriesBoxName = 'entries';

/// Registers the `entries` feature into the project's single `get_it`
/// instance (`sl`) — mirrors `features/account/account_injection.dart`'s
/// pattern. Called from `setupCoreDependencies()` right after
/// `Hive.initFlutter()` (Code Map), which must already have run by the
/// time this opens its box.
Future<void> registerEntriesFeature() async {
  final entriesBox = await Hive.openBox<Map>(entriesBoxName);
  sl.registerSingleton<Box<Map>>(entriesBox);

  sl.registerLazySingleton<EntriesRemoteDataSource>(
    () => EntriesRemoteDataSource(sl<ApiClient>()),
  );

  sl.registerLazySingleton<EntriesRepository>(
    () => EntriesRepositoryImpl(
      remoteDataSource: sl<EntriesRemoteDataSource>(),
      entriesBox: sl<Box<Map>>(),
    ),
  );

  // spec-4-2 — one shared tracker for all three capture cubits
  // (`capture_injection.dart`) *and* `MeusRegistrosCubit` below, so a
  // pending write started from any capture cubit is visible to the other
  // regardless of which "+" tap created it (Design Notes).
  sl.registerLazySingleton<PendingEntryWriteTracker>(
    () => PendingEntryWriteTrackerImpl(repository: sl<EntriesRepository>()),
    dispose: (tracker) => tracker.dispose(),
  );

  // spec-6-4 (RF10) — the shared use case `ChatCubit.bookmarkMessage`
  // depends on (AGENTS.md's RF10 rule), registered here (not in
  // `chat_injection.dart`) since it wraps `EntriesRepository`, the entries
  // feature's own port; `registerChatFeature()` runs after this one
  // (`injection_container.dart`), so `sl<SaveChatMessageAsEntryUseCase>()`
  // is always already registered by the time `chat_injection.dart` wires
  // it into `ChatCubit`.
  sl.registerLazySingleton<SaveChatMessageAsEntryUseCase>(
    () => SaveChatMessageAsEntryUseCaseImpl(sl<EntriesRepository>()),
  );

  // spec-4-1 — `MeusRegistrosCubit` is a `lazySingleton`, not a factory
  // (Code Map/Boundaries), like `AccountSettingsCubit`: long-lived, so
  // `dispose:` wires its `close()` into `get_it`'s own reset lifecycle,
  // same convention `account_injection.dart` already uses.
  sl.registerLazySingleton<MeusRegistrosCubit>(
    () => MeusRegistrosCubit(
      sl<EntriesRepository>(),
      sl<PendingEntryWriteTracker>(),
    ),
    dispose: (cubit) => cubit.close(),
  );

  // spec-5-1 — `EntriesSearchCubit` is a `lazySingleton` too (Code Map),
  // mirroring `MeusRegistrosCubit` immediately above: long-lived, so
  // `dispose:` wires its `close()` into `get_it`'s own reset lifecycle the
  // same way.
  sl.registerLazySingleton<EntriesSearchCubit>(
    () => EntriesSearchCubit(sl<EntriesRepository>()),
    dispose: (cubit) => cubit.close(),
  );

  // spec-4-4 — a `factory`, not a `lazySingleton` (Code Map): each visit to
  // `/meus-registros/:id` gets its own throwaway instance
  // (`EntryDetailScreen`'s own `dispose()` closes it), mirroring the
  // capture cubits' own factory shape rather than `MeusRegistrosCubit`'s
  // long-lived one.
  sl.registerFactory<EntryDetailCubit>(
    () => EntryDetailCubit(
      sl<EntriesRepository>(),
      sl<PendingEntryWriteTracker>(),
      sl<SessionRepository>(),
    ),
  );
}

import 'package:fpdart/fpdart.dart';

import '../../../../core/failure/failure.dart';
import '../entities/entries_page.dart';
import '../entities/entry.dart';

/// The port later epics extend (Code Map) — `features/capture/` depends on
/// this abstract class only, never `entries/data` or `entries/presentation`
/// (RNF06).
abstract class EntriesRepository {
  /// Posts to `entries-create` (`ApiClient.post`, via
  /// `EntriesRemoteDataSource`) and, on success, writes the entry through
  /// to the `entries` Hive box before returning `Right` (Boundaries) — a
  /// caller that only reads the returned [Entry] never needs to touch the
  /// box itself. Every [Failure] — including
  /// [Failure.networkOffline] — is returned as `Left`, unmapped and
  /// un-retried; the caller decides what to do with it (RNF09).
  ///
  /// spec-6-4 — [chatMessageId] is sent only when non-null (the pre-
  /// reserved `Entry.chatMessageId`/`EntrySource.chat` slot, Boundaries:
  /// "not a new architectural call"); every caller before RF10 passed
  /// `null` implicitly, so this is purely additive. Idempotent at the
  /// backend level for a given [chatMessageId] — a repeat call with the
  /// same value never creates a second Entry (epic context's own
  /// Technical Decisions).
  Future<Either<Failure, Entry>> create({
    required String content,
    required EntrySource source,
    int? mediaDurationSeconds,
    String? chatMessageId,
  });

  /// Calls `entries-list` (`ApiClient.get`, via
  /// `EntriesRemoteDataSource`), newest-first by `occurredAt` — server
  /// behavior assumed, undocumented (Code Map, decided per AGENTS.md
  /// policy: "where `docs/input/` is silent... decide and proceed").
  ///
  /// spec-5-2 — [source]/[dateFrom]/[dateTo] are forwarded to
  /// `entries-list` as its own `source`/`dateFrom`/`dateTo` query
  /// parameters (`EntriesRemoteDataSource.list()`'s own doc), each only
  /// when non-null; combining more than one narrows with AND logic (the
  /// backend's own semantics, RF06 Acceptance Criteria) — this repository
  /// does no client-side filtering/joining of its own (AD-9).
  ///
  /// On [Failure.networkOffline]/[Failure.networkTimeout] specifically,
  /// falls back to a full dump of the `entries` Hive box, sorted
  /// `occurredAt` desc, with `EntriesPage.nextCursor: null` (Boundaries) —
  /// every *other* [Failure] (e.g. [Failure.authExpired]) propagates as
  /// `Left`, unmapped (RNF09). That fallback (`cursor == null` only) stays
  /// filter-oblivious regardless of [source]/[dateFrom]/[dateTo] — AD-9:
  /// the cache is never locally filtered, so an offline first page always
  /// renders the full cached list even with filters active.
  ///
  /// A successful page persists every item to the `entries` Hive box
  /// *before* returning `Right` — same "persist then return" ordering
  /// [create] already uses.
  Future<Either<Failure, EntriesPage>> list({
    String? cursor,
    int limit = 20,
    EntrySource? source,
    DateTime? dateFrom,
    DateTime? dateTo,
  });

  /// spec-4-4 (RF07) — calls `entries-get` (`ApiClient.get`, via
  /// `EntriesRemoteDataSource`) with [id] as the one path parameter, then
  /// persists the fetched entry to the `entries` Hive box (`put`) *before*
  /// returning `Right` — same "persist then return" ordering
  /// [create]/[list] already use. AD-11 keeps this port create+read-only,
  /// not count-capped — [search] (spec-5-1) added a fourth method without
  /// contradicting that.
  ///
  /// On [Failure.networkOffline]/[Failure.networkTimeout] specifically,
  /// falls back to `entriesBox.get(id)` if present; a cache miss propagates
  /// the original failure unchanged (no synthesized not-found — that
  /// distinction belongs to whichever `Failure` the backend/network
  /// actually produced). Every *other* [Failure] — including
  /// [Failure.notFound] for an id that never existed or belongs to another
  /// user — is returned as `Left`, unmapped (RNF09); RNF04 (identical
  /// treatment for both causes) is the caller's own rendering job, never
  /// this repository's.
  Future<Either<Failure, Entry>> getById(String id);

  /// spec-5-1 — calls `entries-search` (`ApiClient.get`, via
  /// `EntriesRemoteDataSource`) with [query] as the one `q` query
  /// parameter (no `limit`/`cursor` — Boundaries). [query] is always
  /// already a non-empty, pre-trimmed string by the time it reaches this
  /// method — `EntriesSearchCubit` owns that guarantee, never this
  /// repository.
  ///
  /// spec-5-3 — [source]/[dateFrom]/[dateTo] are forwarded to
  /// `entries-search` as its own `source`/`dateFrom`/`dateTo` query
  /// parameters, each only when non-null — same AND-narrowing convention
  /// [list]'s own doc already gives, now carried by `EntriesSearchCubit`'s
  /// own filter fields (`updateFilters()`) instead of `MeusRegistrosCubit`'s
  /// (the two cubits never share state directly, RNF06 — only
  /// `MeusRegistrosScreen` bridges them).
  ///
  /// On success, persists every returned entry to the `entries` Hive box
  /// (`putAll`) *before* returning `Right` — same "persist then return"
  /// ordering [list]/[getById] already use. Unlike [list]/[getById], there
  /// is no offline/timeout cache fallback here (AD-9: no client-side
  /// vector index) — every [Failure], including
  /// [Failure.networkOffline], is returned as `Left`, unmapped (RNF09).
  Future<Either<Failure, List<Entry>>> search(
    String query, {
    EntrySource? source,
    DateTime? dateFrom,
    DateTime? dateTo,
  });
}

import 'package:connectivity_plus/connectivity_plus.dart';
import 'package:hive_ce/hive_ce.dart';

import '../../core/di/injection_container.dart';
import '../../core/network/api_client.dart';
import '../entries/domain/usecases/save_chat_message_as_entry_use_case.dart';
import 'data/datasources/chat_remote_data_source.dart';
import 'data/repositories/chat_repository_impl.dart';
import 'data/services/connectivity_plus_watcher.dart';
import 'domain/repositories/chat_repository.dart';
import 'domain/services/connectivity_watcher.dart';
import 'presentation/cubit/chat_cubit.dart';

/// The `chat_sessions`/`chat_messages` Hive box names — two boxes (Code
/// Map: "Hive box cache for `listSessions`/`listMessages`"), mirroring
/// `entries_injection.dart`'s `entriesBoxName` pattern but split in two
/// since each caches a structurally different DTO shape.
const chatSessionsBoxName = 'chat_sessions';
const chatMessagesBoxName = 'chat_messages';

/// Registers the `chat` feature into the project's single `get_it`
/// instance (`sl`) — mirrors `entries_injection.dart`'s pattern. Called
/// from `setupCoreDependencies()` after `Hive.initFlutter()` has already
/// run (Code Map), same ordering requirement `registerEntriesFeature()`
/// documents for itself.
Future<void> registerChatFeature() async {
  final sessionsBox = await Hive.openBox<Map>(chatSessionsBoxName);
  final messagesBox = await Hive.openBox<Map>(chatMessagesBoxName);
  // `instanceName` disambiguates the two `Box<Map>` singletons from each
  // other and from `entries_injection.dart`'s own unnamed one — `get_it`
  // keys a registration by type + instance name, so three same-typed
  // singletons coexist safely.
  sl.registerSingleton<Box<Map>>(
    sessionsBox,
    instanceName: chatSessionsBoxName,
  );
  sl.registerSingleton<Box<Map>>(
    messagesBox,
    instanceName: chatMessagesBoxName,
  );

  sl.registerLazySingleton<ChatRemoteDataSource>(
    () => ChatRemoteDataSource(sl<ApiClient>()),
  );

  sl.registerLazySingleton<ChatRepository>(
    () => ChatRepositoryImpl(
      remoteDataSource: sl<ChatRemoteDataSource>(),
      sessionsBox: sl<Box<Map>>(instanceName: chatSessionsBoxName),
      messagesBox: sl<Box<Map>>(instanceName: chatMessagesBoxName),
    ),
  );

  // spec-6-3 — one real `Connectivity`/`ConnectivityWatcher` for the
  // app's lifetime, mirroring `capture_injection.dart`'s own
  // `record_pkg.AudioRecorder`/`MicRecorder` registration shape.
  sl.registerLazySingleton<Connectivity>(Connectivity.new);
  sl.registerLazySingleton<ConnectivityWatcher>(
    () => ConnectivityPlusWatcher(connectivity: sl<Connectivity>()),
  );

  // A `lazySingleton`, not a factory (Code Map), mirroring
  // `MeusRegistrosCubit`: long-lived, so a session bootstrapped on one
  // visit to Home/Chat survives leaving and returning within the same app
  // session (`ChatCubit.init()`'s own no-op guard). `dispose:` wires
  // `close()` into `get_it`'s own reset lifecycle, same convention every
  // other long-lived cubit in this codebase already uses.
  // spec-6-4 (RF10) — `sl<SaveChatMessageAsEntryUseCase>()` is registered
  // by `registerEntriesFeature()`, which `setupCoreDependencies()` always
  // runs before this function (`injection_container.dart`), so it's
  // already available here; only the use-case file is imported above,
  // never `entries/domain/repositories/entries_repository.dart` (AGENTS.md
  // RF10 rule).
  sl.registerLazySingleton<ChatCubit>(
    () => ChatCubit(
      sl<ChatRepository>(),
      sl<ConnectivityWatcher>(),
      sl<SaveChatMessageAsEntryUseCase>(),
    ),
    dispose: (cubit) => cubit.close(),
  );
}

import '../../core/di/injection_container.dart';
import 'data/datasources/account_remote_data_source.dart';
import 'data/repositories/account_settings_repository_impl.dart';
import 'domain/repositories/account_settings_repository.dart';
import 'presentation/cubit/account_settings_cubit.dart';

/// Registers the `account` feature into the project's single `get_it`
/// instance (`sl`) — mirrors `features/vault/vault_injection.dart`'s
/// pattern. Called from `setupCoreDependencies()` right after
/// `registerVaultFeature()` (Code Map).
void registerAccountFeature() {
  sl.registerLazySingleton<AccountRemoteDataSource>(
    () => AccountRemoteDataSource(sl()),
  );

  // The epic's one new DI-singleton access point for the account's
  // `biometricEnabled` preference — registered as a singleton so every
  // consumer (`main.dart`'s boot fetch; `core/navigation/app_router.dart`'s
  // `/vault` builder; the Configurações screen's own cubit) shares the same
  // `biometricEnabledStream`, not a fresh instance each. `dispose:` wires
  // `AccountSettingsRepository.dispose()` into `get_it`'s own reset
  // lifecycle, so `resetCoreDependencies()` (`sl.reset()`) closes its
  // `StreamController` instead of leaking one on every test teardown.
  sl.registerLazySingleton<AccountSettingsRepository>(
    () => AccountSettingsRepositoryImpl(remoteDataSource: sl()),
    dispose: (repository) => repository.dispose(),
  );

  // Review finding: `AccountSettingsCubit`'s constructor subscribes to
  // `biometricEnabledStream`; only its own `close()` cancels that
  // subscription, which nothing previously called — `dispose:` wires it
  // into `get_it`'s own reset lifecycle, same convention as every other
  // registration in this file.
  sl.registerLazySingleton<AccountSettingsCubit>(
    () => AccountSettingsCubit(sl()),
    dispose: (cubit) => cubit.close(),
  );
}

import 'package:fpdart/fpdart.dart';

import '../../../../core/failure/failure.dart';
import '../entities/chat_insight.dart';
import '../entities/chat_message.dart';
import '../entities/chat_session.dart';
import '../entities/chat_stream_event.dart';

/// The chat feature's one port — `features/chat/presentation` depends on
/// this abstract class only, never `chat/data` (RNF06). Every method but
/// [sendMessage] returns `Future<Either<Failure, T>>` (RNF09); [sendMessage]
/// alone returns a `Stream` given the SSE nature of its response
/// (Boundaries).
abstract class ChatRepository {
  /// Calls `chat-sessions-list` (`ApiClient.get`, via
  /// `ChatRemoteDataSource`) — works offline via the `chat_sessions` Hive
  /// box (Code Map): on [Failure.networkOffline]/[Failure.networkTimeout],
  /// falls back to a full dump of that box, same "cache fallback"
  /// convention `EntriesRepositoryImpl.list()` already uses for its own
  /// first/fresh page. Every other [Failure] propagates as `Left`,
  /// unmapped (RNF09).
  Future<Either<Failure, List<ChatSession>>> listSessions();

  /// Calls `chat-sessions-create` (`ApiClient.post`) with no title
  /// (Boundaries: "`chat-sessions-create` with no title") — blocked
  /// offline per `requirements.md` ("`POST /chat/sessions` — blocked
  /// offline"), so unlike [listSessions] there is no cache fallback here:
  /// every [Failure], including [Failure.networkOffline], is returned as
  /// `Left`, unmapped. On success, persists the new session to the
  /// `chat_sessions` Hive box before returning `Right`, same
  /// "persist then return" ordering [listSessions] already uses.
  Future<Either<Failure, ChatSession>> createSession();

  /// Calls `chat-messages-list` (`ApiClient.get`, [sessionId] appended as
  /// the one trailing path segment) — works offline via the
  /// `chat_messages` Hive box, same cache-fallback convention
  /// [listSessions] already uses, filtered to [sessionId] and sorted by
  /// `seq` ascending (the backend's own "ordered by seq", `openapi.yaml`).
  Future<Either<Failure, List<ChatMessage>>> listMessages(String sessionId);

  /// Calls `chat-messages-send` (`ApiClient.postStream`, [sessionId]
  /// appended as the one trailing path segment) with `{content}` — the
  /// one streaming exception to this port's otherwise all-`Future` shape
  /// (Boundaries/RNF09: "every other method returns
  /// `Future<Either<Failure, T>>`"). No connectivity resolves immediately
  /// to a single `Left(Failure.networkOffline)` emission, never queued
  /// (Boundaries) — `ApiClient.postStream`'s own first awaited `Dio.post`
  /// call surfaces that failure before any byte streams. A connection that
  /// closes without a `done`/`error` SSE event is surfaced as a single
  /// trailing `Left(Failure.networkTimeout)` (Design Notes: "the taxonomy
  /// has no dedicated 'dropped stream' code"). No local write queue, no
  /// Hive persistence of sent messages (Design Notes: chat holds no local
  /// write queue for this story).
  Stream<Either<Failure, ChatStreamEvent>> sendMessage(
    String sessionId,
    String content,
  );

  /// spec-6-3 — calls `chat-messages-retry` (`ApiClient.postStream`,
  /// [sessionId] then [userMessageId] appended as the two trailing path
  /// segments, `data: const {}`) — regenerates the AI response for an
  /// already-persisted user message without re-sending its content
  /// (Boundaries: "never a duplicate question"). Same streaming shape and
  /// terminal handling as [sendMessage] (SSE events via
  /// `ChatRemoteDataSource`'s shared buffer/parse helper); [userMessageId]
  /// must be a real, already-persisted user message id — `ChatCubit`
  /// itself never calls this with one that's `null` (Boundaries: "Never
  /// calling `chat-messages-retry` with no `serverId`"), falling back to
  /// [sendMessage] instead in that case.
  Stream<Either<Failure, ChatStreamEvent>> retryMessage(
    String sessionId,
    String userMessageId,
  );

  /// spec-6-5 — calls `chat-insight-create` (`ApiClient.post`, [sessionId]
  /// appended as the one trailing path segment) with `{triggerType:
  /// triggerType.wireValue, triggerKey}`. `ChatCubit` fires this
  /// fire-and-forget, unawaited, through `isolatedSideEffect` — its first
  /// unawaited caller (Boundaries). `null` means "no insight to show": a
  /// successful (200) response whose `status` isn't `'ready'` — RF08:
  /// "never an HTTP error; a failure becomes status='failed'", so a
  /// genuine backend-side generation failure still arrives as a `Right`
  /// here, just carrying `null`. Only a transport-level problem (offline,
  /// timeout, malformed shape, etc.) surfaces as `Left`, unmapped
  /// (RNF09) — `ChatCubit` drops both cases silently either way
  /// (Boundaries).
  Future<Either<Failure, ChatInsight?>> generateInsight(
    String sessionId, {
    required InsightTriggerType triggerType,
    required String triggerKey,
  });
}

